import { ComponentProps } from "react";
import { Meta, StoryObj } from "@storybook/react";
import { action } from "storybook/actions";
import {
  WithMockedDate,
  WithResetQueryCache,
  withMockedDate,
  withQueryProvider,
  withResetQueryCache,
} from "../../../../../../.storybook/preview";
import { DateHelper, LocalStorageHelper, throwError } from "@/core/helpers";
import { QueryProvider } from "@/core/providers";
import { AlbumResponse, MediaResponse } from "@parksandresorts/webapiproxy-types";
import {
  MOCKED_DATE,
  daysFromToday,
  delay,
  fetchAlbumMock,
  getMediaOnQrCodeAccountMock,
  clickOnElement,
  elementIsNotInDocument,
  typeValue,
  waitForVisibleElement,
  withFocusedMediaModalMinHeight,
} from "../../digital-ride-media-storybook-helpers";
import DigitalRideMediaQrCodeConnectBlock from "../../qr-code-connect-block/digital-ride-media-qr-code-connect-block";
import { expect } from "storybook/test";

type StoryArgs = ComponentProps<WithResetQueryCache<WithMockedDate<typeof DigitalRideMediaQrCodeConnectBlock>>> & {
  savedAlbumIds: Array<string>;
};

const meta: Meta<StoryArgs> = {
  title: "Modules/Digital Ride Media/Save To Album",
  component: DigitalRideMediaQrCodeConnectBlock,
  argTypes: {
    mockedDate: {
      control: {
        type: "date",
      },
    },
  },
  decorators: [withResetQueryCache, withMockedDate, withQueryProvider, withFocusedMediaModalMinHeight],
  parameters: {
    chromatic: { delay: 4000 },
  },
  render: function StoryComponent({ ...args }) {
    LocalStorageHelper.setItem("savedRideMediaAlbumIds", args.savedAlbumIds, undefined);
    return (
      <QueryProvider>
        <div style={{ background: "var(--foundation-color-primary-200)" }}>
          <i>
            <b>Information about story:</b>
            <br />
            Stories only shows button to save in existing or new album. When clicked they stay in loading mode. In
            reality the album block is opened, with the saved media highlighted.
            <br />
            See `Album Block` stories to see how that looks, and other cases of album data.
            <br />
            See `Search Block` stories to see how Save to album component works when searching for media instead of
            scanning QR code.
            <br />
            See `Search Album Form` stories to see different cases of searching for an album.
          </i>
        </div>
        <DigitalRideMediaQrCodeConnectBlock
          {...args}
          navigateToAlbum={action("navigateToAlbum")}
          service={{
            getMediaOnQrCodeAccount: async (_accountId) => {
              await delay(1000);
              return getMediaOnQrCodeAccountMock();
            },
            // The loading state is not visible for the Chromatic snapshot, so we do not simulate this in the tests.
            // If manually clicked (connect to album or create new album) the buttons will stay in loading state
            connectQrCodeToAlbum: () =>
              new Promise<MediaResponse>(() => {
                /* never resolves */
              }),
            createNewAlbum: () =>
              new Promise<AlbumResponse>(() => {
                /* never resolves */
              }),
            fetchAlbum: fetchAlbumMock,
            // Functions not needed for the stories
            fetchAlbumMedia: () => throwError("Not implemented"),
            searchForMedia: () => throwError("Not implemented"),
            createNewAlbumWithInitialMedia: () => throwError("Not implemented"),
            addMediaToAlbum: () => throwError("Not implemented"),
            updateName: () => throwError("Not implemented"),
            deleteMediaFromAlbum: () => throwError("Not implemented"),
            deleteAlbum: () => throwError("Not implemented"),
            addContactInformationToAlbum: () => throwError("Not implemented"),
          }}
        />
      </QueryProvider>
    );
  },
};

export default meta;

type Story = StoryObj<typeof meta>;

export const WithNoPreviouslySavedAlbums: Story = {
  args: {
    mockedDate: new Date(MOCKED_DATE),
    qrCodeAccountId: "12345678",
    savedAlbumIds: [],
  },
  play: async ({ canvasElement }) => {
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-save-to-album-create-new-album-button",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-first-part",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-second-part",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-third-part",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-search-button",
    });
  },
};

export const WithPreviouslySavedAlbums: Story = {
  args: {
    ...WithNoPreviouslySavedAlbums.args,
    savedAlbumIds: ["KOL-TOD-NON-PUR", "KOL-LAS-NON-PUR"],
  },
  play: async ({ canvasElement }) => {
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-visit-date-KOL-TOD-NON-PUR",
      assert: (el) => expect(el).toHaveTextContent(DateHelper.toStringDDMonthYear(daysFromToday(0))),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-save-to-album-or-divider",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "expand-content-toggle-button-collapsed",
    });
    await elementIsNotInDocument({
      canvasElement,
      testIds: ["digital-ride-media-save-to-existing-album-button-KOL-LAS-NON-PUR"],
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-save-to-existing-album-button-KOL-TOD-NON-PUR",
    });
  },
};

export const WithPreviouslySavedUnlockedAlbums: Story = {
  args: {
    ...WithPreviouslySavedAlbums.args,
    savedAlbumIds: ["KOL-TOD-NON-PUR", "KOL-LAS-NON-PUR", "KOL-TOD-ALB-UNL", "KOL-TOD-PUR-SOM"],
  },
  play: async ({ canvasElement }) => {
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-albums-list",
      assert: (el) =>
        expect(el.querySelector("li")).toHaveAttribute(
          "data-testid",
          "digital-ride-media-existing-album-KOL-TOD-ALB-UNL",
        ),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-KOL-TOD-ALB-UNL",
      assert: (el) => expect(el).toHaveAttribute("data-is-unlocked", "true"),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-save-to-unlocked-album-info",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-KOL-TOD-NON-PUR",
      assert: (el) => expect(el).toHaveAttribute("data-is-unlocked", "false"),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-KOL-TOD-PUR-SOM",
      assert: (el) => expect(el).toHaveAttribute("data-is-unlocked", "false"),
    });
  },
};

export const WithSearchForExistingAlbum: Story = {
  args: {
    ...WithNoPreviouslySavedAlbums.args,
  },
  play: async ({ canvasElement }) => {
    await typeValue({
      canvasElement,
      testCases: [
        ["digital-ride-media-search-album-form-album-code-first-part", "TOD"],
        ["digital-ride-media-search-album-form-album-code-second-part", "NON"],
        ["digital-ride-media-search-album-form-album-code-third-part", "PUR"],
      ],
    });
    await clickOnElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-search-button",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-save-to-existing-album-button-KOL-TOD-NON-PUR",
    });
  },
};

